#!/usr/bin/env python3
"""Original SH-2 CD-DA/SCSP routing guest. MIT: adjacent LICENSE.

ST-162 §8.2.2 play and ST-077 table 4.31 external stereo routing.
The host supplies an original three-sector audio track, with optional PRE.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_cd_drive import command, store
from build_scu import assembler

HERE = Path(__file__).resolve().parent


def build():
    source = store(0x25B00400, 0x020F)
    source += store(0x25B00216, 0x00FF)  # EXTS0: left only, full send
    source += store(0x25B00236, 0x00EF)  # EXTS1: right only, full send
    source += command([0x1080, 150, 0x0080, 3], 'play', 0x06009000)
    source += 'load 0x06009010,r1\nload 0x600d,r0\nmov.l r0,@r1\nsleep\n'
    rom = bytearray(524288)
    struct.pack_into('>II', rom, 0, 0x200, 0x06100000)
    code = assembler.assemble(source, base=0x200)
    rom[0x200:0x200 + len(code)] = code
    lines = ['# Original CD-DA routing guest. MIT: adjacent LICENSE.',
             '# Generated by build_cdda.py; unspecified bytes are zero.']
    for address in range(0, len(rom), 16):
        block = rom[address:address + 16]
        if any(block):
            lines.append(f'{address:04X} ' + ' '.join(f'{w:04X}' for w in struct.unpack('>8H', block)))
    return '\n'.join(lines) + '\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    text, digest = build()
    path = HERE / 'cdda.hex'
    if args.check:
        assert path.read_text() == text, 'Rebuild cdda.hex'
    else:
        path.write_text(text)
    print(f'{"Verified" if args.check else "Built"} cdda.hex; expanded ROM SHA-256 {digest}')
